    if (!state.library.length) { if (!silent) log('Library is empty!'); state.drewEmpty = true; break; }
    const reps=replacementEffectHints(); if(reps.length && !silent && i===0) log(`Rules hint: ${reps.join(', ')} may modify this draw or event.`);
