  L.push('', 'MOST COMMON PHRASE STARTS');
  for (const [, e] of top(res.starts, 60)) L.push(`  ${e.n} | ${e.kind} | ${e.shape} | ${e.ex.join('; ')}`);
  L.push('', 'KEYWORDS THE APP ONLY EXPLAINS (does not enforce)');
