    m.body.append(h('div', { class: 'psub', text }), h('div', { class: 'choose-list' }, labels.map((l, i) => h('button', { class: 'choose-opt', text: l, onclick: () => end(i) }))));
    m.foot.append(h('button', { text: 'Neither', onclick: () => end(null) }));
